export enum MediaManagerMediaType {
  IMAGE = 'IMAGE',
  ALL_MEDIA = 'ALL_MEDIA',
  VIDEO = 'VIDEO',
  AUDIO = 'MUSIC',
}

type SDKMediaBase = {
  id: string;
  title: string;
  fullTitle: string;
  fileUrl: string;
  fileName: string;
  fileSize: number;
  uri: string;
};

export type SDKImageMedia = SDKMediaBase & {
  mediaType: 'picture';
  height: number;
  width: number;
};

export type SDKVideoMedia = SDKMediaBase & {
  mediaType: 'video';
  fileOutput: {
    video: {
      format: string;
      quality: string;
      url: string;
    }[];
    image: {
      url: string;
      width: number;
      height: number;
    }[];
  };
  height: number;
  width: number;
};

export type SDKAudioMedia = SDKMediaBase & {
  mediaType: 'music';
  fileOutput: {
    audio: {
      url: string;
    }[];
  };
};

export type SDKFileMedia = SDKImageMedia | SDKVideoMedia | SDKAudioMedia;
