import { TIPTAP_FILE_TYPE } from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { File as Component } from './component.js';

const name = TIPTAP_FILE_TYPE;

export const tiptapExtensions: RicosExtension[] = [
  createRicosNodeExtension({
    groups: ['overlay', 'draggable', 'not-overtypable'],
    type: 'react-node',
    name,
    reconfigure: (
      config: NodeConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings: Record<string, unknown>
    ) => ({
      ...config,
      addOptions: () => settings,
    }),
    Component,
    createExtensionConfig() {
      return {
        name: this.name,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          containerData: null,
          src: null,
          name: null,
          type: null,
          size: null,
          pdfSettings: null,
          mimeType: null,
          path: null,
          sizeInKb: null,
          loading: {
            default: false,
          },
          error: null,
        }),
        addCommands() {
          return {};
        },
      };
    },
  }),
];
