import { definePmNodeConverter } from './../pm-converters/types.js';
import type { FileData } from './../ricos-schema/next-schema/index.js';
import { Node_Type } from './../ricos-schema/next-schema/index.js';

export const fileUploadConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.FILE],
    convert: node => ({
      type: Node_Type.FILE,
      attrs: {
        ...node.fileData,
        id: node.id,
      },
    }),
  },
  fromPm: {
    types: [Node_Type.FILE],
    convert: node => {
      const { id, loading, error, animation, ...data } = node.attrs || {};

      if (loading || error) {
        return undefined;
      }

      return {
        type: Node_Type.FILE,
        id,
        nodes: [],
        fileData: {
          ...(data as FileData),
          ...(animation ? { animation } : {}),
        },
      };
    },
  },
});
