import { Attachement, AttachmentSmall } from '@wix/wix-ui-icons-common/lazy';

import {
  type EditorPluginCreator,
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import { fileUploadConverter } from './file-upload-converter.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { handleFileUpload } from './handle-file-upload.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { FilePluginEditorConfig } from './types.js';
import { FILE_UPLOAD_TYPE } from './types.js';

export const pluginFileUpload: EditorPluginCreator<FilePluginEditorConfig> = config => {
  const pluginConfig: FilePluginEditorConfig = {
    type: 'file' as const,
    ...DEFAULTS.config,
    ...config,
  };
  return {
    config: pluginConfig,
    pmMarkConverters: [],
    pmNodeConverters: [fileUploadConverter],
    type: FILE_UPLOAD_TYPE,
    tiptapExtensions,
    toolbar: {
      names: [RicosPluginToolbarNames.FILE],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getAddButtons: (config, services) => getAddButtons(config as any, services),
    getQuickActions: ({ pluginServices, config }) => [
      {
        id: Node_Type.FILE,
        title: 'QuickActionsPlugin_ActionTitle_File',
        icon: pluginServices?.context.isMobile ? Attachement : AttachmentSmall,
        section: quickActionsModalSections.Media,
        tags: ['document', 'attachment', 'upload', 'download', 'resource'],
        command: ({ publicCommands }) => {
          handleFileUpload({ services: pluginServices, config: config as any, publicCommands });
        },
      },
    ],
  };
};
