import { Box, SidePanel } from '@wix/design-system';
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';

import { TOOLBAR_DROPDOWN_PANEL } from './data-hooks.js';
import classes from './dropdown-modal-scss.js';

/** Panels that ask for no width still have to be wide enough to read. */
const DEFAULT_MIN_WIDTH = 160;

type Props = {
  title: string;
  options: React.ReactNode;
  minWidth?: number;
  maxHeight?: number;
  onCloseButtonClick: () => void;
  className?: string;
  dataHook?: string;
};

/**
 * The surface a ricos dropdown's rows are listed on: WDS `SidePanel` on mobile,
 * WDS `Box` on desktop. `Box` is layout only — it forwards no event handlers and
 * no tab index, and it spreads anything it does not recognise into its inline
 * style — so nothing here may depend on the surface handling events. It does not
 * have to: selection, tab order and keyboard handling live on the rows
 * (`_shared/list-item-select`), and the enclosing modal owns focus and
 * click-outside.
 */
export const DropdownModal: React.FC<Props> = ({
  options,
  minWidth = DEFAULT_MIN_WIDTH,
  maxHeight,
  className,
  onCloseButtonClick,
  title,
  dataHook,
}) => {
  const { isMobile } = useContext(RicosContext);

  if (isMobile) {
    return (
      <SidePanel
        closeButtonProps={{ onClick: onCloseButtonClick }}
        width="100%"
        maxHeight="50vh"
        height="fit-content"
      >
        <SidePanel.Header title={title} />
        <SidePanel.Content className={classes.mobileContent}>{options}</SidePanel.Content>
      </SidePanel>
    );
  }

  return (
    <Box
      direction="vertical"
      className={classNames(classes.root, className)}
      dataHook={classNames(TOOLBAR_DROPDOWN_PANEL, dataHook)}
      role="listbox"
      minWidth={minWidth}
      maxHeight={maxHeight}
    >
      {options}
    </Box>
  );
};
