import type { FileComponentData, UpdateEntityFileSelectFunc } from './../ricos-content/index.js';
import type { FileData } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { UploadFunction } from './../_shared/with-file-size-limitation.js';

export const FILE_UPLOAD_TYPE = 'wix-draft-plugin-file-upload';

export interface FilePluginEditorConfig {
  type: 'file';
  /**
   * MIME type filter for file selection dialog.
   * Controls which file types are allowed to be selected when uploading files.
   *
   * @default '*'
   *
   * @example
   * // Accept all files
   * accept: '*'
   *
   * @example
   * // Accept only PDF files
   * accept: 'application/pdf'
   *
   * @example
   * // Accept multiple file types
   * accept: 'image/*,video/*,application/pdf'
   */
  accept?: string;
  /**
   * Custom file upload function that overrides the default upload behavior.
   * This function is called when a file is selected for upload and handles the actual file upload process.
   */
  onFileSelected?: UploadFunction<FileComponentData>;

  handleFileSelection?: (
    updateEntity: UpdateEntityFileSelectFunc<FileComponentData[] | FileComponentData>
  ) => void;
}
export interface FilePluginViewerConfig {
  resolveFileUrl?: (file: FileUploadData) => Promise<string | undefined>;
  downloadTarget?: string;
}

export type FileUploadData = Pick<
  FileData,
  'type' | 'path' | 'mimeType' | 'name' | 'size' | 'pdfSettings'
> & {
  id?: string;
  privacy?: 'private' | 'public';
};
